def eval_expression(expr: str) -> float:
    """
    Evaluates a mathematical expression string following the order of operations.
    Supports +, -, *, /, parentheses, and negative numbers.
    Raises ZeroDivisionError if division by zero occurs.
    """
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
        elif c == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        elif c in '+-*/':
            tokens.append(('OP', c))
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            num_str = expr[i:j]
            tokens.append(('NUM', num_str))
            i = j
        else:
            raise ValueError(f"Unexpected character: {c}")

    # Parse tokens using recursive descent parser
    pos = 0
    total_tokens = len(tokens)

    def peek():
        nonlocal pos
        if pos < total_tokens:
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def parse_expression():
        """Parse addition and subtraction (lowest precedence)"""
        node = parse_term()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = consume()[1]
            right = parse_term()
            if op == '+':
                node = ('ADD', node, right)
            else:
                node = ('SUB', node, right)
        return node

    def parse_term():
        """Parse multiplication and division (higher precedence)"""
        node = parse_factor()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('*', '/'):
            op = consume()[1]
            right = parse_factor()
            if op == '*':
                node = ('MUL', node, right)
            else:
                node = ('DIV', node, right)
        return node

    def parse_factor():
        """Parse numbers, parenthesized expressions, and unary minus/plus"""
        token = peek()
        if token is None:
            raise ValueError("Unexpected end of expression")

        if token[0] == 'NUM':
            consume()
            return ('NUM', float(token[1]))

        if token[0] == 'LPAREN':
            consume()
            node = parse_expression()
            if not peek() or peek()[0] != 'RPAREN':
                raise ValueError("Expected closing parenthesis")
            consume()
            return node

        if token[0] == 'OP' and token[1] in ('+', '-'):
            op = consume()[1]
            operand = parse_factor()
            if op == '-':
                return ('NEG', operand)
            else:
                return operand

        raise ValueError(f"Unexpected token: {token}")

    def evaluate(node):
        """Evaluate the parse tree"""
        if node[0] == 'NUM':
            return node[1]
        elif node[0] == 'ADD':
            return evaluate(node[1]) + evaluate(node[2])
        elif node[0] == 'SUB':
            return evaluate(node[1]) - evaluate(node[2])
        elif node[0] == 'MUL':
            return evaluate(node[1]) * evaluate(node[2])
        elif node[0] == 'DIV':
            left = evaluate(node[1])
            right = evaluate(node[2])
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            return left / right
        elif node[0] == 'NEG':
            return -evaluate(node[1])
        else:
            raise ValueError(f"Unknown node type: {node[0]}")

    result = evaluate(parse_expression())

    # Verify all tokens were consumed
    if pos != total_tokens:
        raise ValueError("Invalid expression")

    return result
